from pathlib import Path
from datetime import datetime, timezone
from typing import IO

BASE_DIR = Path.cwd().parent
LINE_LENGTH = 120


def write_statement(outputfile: IO[str], statement: str) -> None:
    if len(statement) > LINE_LENGTH:
        statement += "  # fmt: skip"
    outputfile.write(statement + "\n")


def generate_object_ids() -> None:
    nodeids = BASE_DIR / "schemas" / "UA-Nodeset-master" / "Schema" / "NodeIds.csv"
    with open(BASE_DIR / "asyncua" / "ua" / "object_ids.py", "w") as outputfile:
        outputfile.write(
            "# AUTOGENERATED!!!\n"
            "\n"
            "\n"
            # Making ObjectIds inherit IntEnum has a huge performance impact!!!!!
            # so we use a normal class and a reverse one for the few places we need it
            "class ObjectIds:\n"
            "    Null = 0\n"
        )
        with open(nodeids) as inputfile:
            for line in inputfile:
                name, nb, datatype = line.split(",")
                write_statement(outputfile, f"    {name} = {nb}")
        outputfile.write('\n\nObjectIdNames = {}\nObjectIdNames[0] = "Null"\n')
        with open(nodeids) as inputfile:
            for line in inputfile:
                name, nb, datatype = line.split(",")
                write_statement(outputfile, f'ObjectIdNames[{nb}] = "{name}"')


def generate_attribute_ids() -> None:
    attributeids = BASE_DIR / "schemas" / "UA-Nodeset-master" / "Schema" / "AttributeIds.csv"
    with open(BASE_DIR / "asyncua" / "ua" / "attribute_ids.py", "w") as outputfile:
        outputfile.write(
            f"# AUTOGENERATED!!! Date: {datetime.now(timezone.utc)}\n"
            "\n"
            "from enum import IntEnum\n"
            "\n"
            "\n"
            "class AttributeIds(IntEnum):\n"
        )
        with open(attributeids) as inputfile:
            for line in inputfile:
                name, nb = line.split(",")
                outputfile.write(f"    {name.strip()} = {nb.strip()}\n")


if __name__ == "__main__":
    generate_object_ids()
    generate_attribute_ids()
    print("generate done!")
